const DRIVE_CLOSE = {
  title: 'Close',
  body: 'Do two easy slides, then say the closing line once and notice how your throat feels.',
  how: [
    'An easy slide is a lip trill or a narrow “voo” that moves up a little, about as far as a spoken question, then back down. Stay in a comfortable speaking range.',
    'Then say, once: “This is the voice I’m choosing today, and I know how to find it comfortably.”',
    'If your voice feels rough, scratchy, or pressed, stop. Do not start another block.'
  ],
  reps: { 20: 'Two easy slides, then the closing line once.', 30: 'Two easy slides, then the closing line once.', 40: 'Two easy slides, then the closing line once.' }
};
const DRIVE_TRILL = 'Lip trill: rest your lips together and blow a steady stream of air so they flutter, with a quiet voice inside the flutter. It should feel easy, like a slow raspberry. If your lips will not flutter, shape a narrow “voo” and use that instead.';
const DRIVE_SLIDE = 'One slide is that sound moving up a little, about the rise of a spoken question, then back down. Stay where speaking is comfortable. Do not aim for a high note.';

